Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class Win32Focus {
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
}
"@
Add-Type -AssemblyName System.Windows.Forms
$hwnd=[IntPtr]67948
if(-not [Win32Focus]::SetForegroundWindow($hwnd)){ throw 'SetForegroundWindow failed' }
Start-Sleep -Milliseconds 500
$fg=[Win32Focus]::GetForegroundWindow()
Write-Output ("foreground=" + $fg.ToInt64())
if($fg.ToInt64() -ne 67948){ throw "Foreground mismatch: $($fg.ToInt64())" }
